begin;
do $$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); admin_id uuid:=gen_random_uuid(); super_id uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); pool uuid; inv uuid; inv2 uuid; users jsonb; prefix text:='qa'||replace(gen_random_uuid()::text,'-','');
begin
 insert into auth.users(id,email,email_confirmed_at,aud,role) select x,x||'@predict-qa.invalid',now(),'authenticated','authenticated' from unnest(array[a,b,c,admin_id,super_id]) x;
 insert into public.profiles(id,username,display_name) select x,prefix||x::text,'QA' from unnest(array[a,b,c,admin_id,super_id]) x;
 insert into public.user_roles(user_id,role) values(a,'user'),(b,'user'),(c,'user'),(admin_id,'admin'),(super_id,'super_admin');
 insert into public.tournaments(id,competition_id,name,status) select t,id,'QA direct invitations rollback','published' from public.competitions limit 1;
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('role','authenticated',true);
 pool:=public.create_pool(t,'QA temporary pool');
 if public.search_pool_users(pool,'qa')<>'[]'::jsonb then raise exception 'FAIL short query'; end if;
 users:=public.search_pool_users(pool,prefix);
 if jsonb_array_length(users)<>3 then raise exception 'FAIL max three'; end if;
 if exists(select 1 from jsonb_array_elements(users) u where u->>'user_id'=a::text) then raise exception 'FAIL owner included'; end if;
 inv:=public.send_pool_invitation(pool,b);
 begin perform public.send_pool_invitation(pool,b);raise exception 'FAIL duplicate';exception when raise_exception then if sqlerrm='FAIL duplicate' then raise;end if;end;
 if exists(select 1 from jsonb_array_elements(public.search_pool_users(pool,prefix||b::text)) u where u->>'user_id'=b::text) then raise exception 'FAIL pending candidate'; end if;
 perform set_config('request.jwt.claim.sub',c::text,true);
 if public.get_my_pool_invitations()<>'[]'::jsonb then raise exception 'FAIL invitations leaked';end if;
 begin perform public.respond_pool_invitation(inv,true);raise exception 'FAIL wrong recipient';exception when insufficient_privilege then null;end;
 begin perform public.search_pool_users(pool,prefix);raise exception 'FAIL outsider search';exception when insufficient_privilege then null;end;
 begin perform public.send_pool_invitation(pool,c);raise exception 'FAIL outsider invite';exception when insufficient_privilege then null;end;
 begin perform public.delete_pool(pool);raise exception 'FAIL outsider delete';exception when insufficient_privilege then null;end;
 begin perform recipient_id from public.invitations;raise exception 'FAIL invitations table readable';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',b::text,true);
 if jsonb_array_length(public.get_my_pool_invitations())<>1 then raise exception 'FAIL missing invitation';end if;
 perform public.respond_pool_invitation(inv,true);
 if not exists(select 1 from public.pool_members where pool_id=pool and user_id=b) or not exists(select 1 from public.tournament_entries where tournament_id=t and user_id=b) then raise exception 'FAIL join';end if;
 begin perform public.delete_pool(pool);raise exception 'FAIL member delete';exception when insufficient_privilege then null;end;
 begin perform public.respond_pool_invitation(inv,true);raise exception 'FAIL reuse';exception when raise_exception then if sqlerrm='FAIL reuse' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 if public.search_pool_users(pool,prefix||b::text)<>'[]'::jsonb then raise exception 'FAIL member candidate';end if;
 inv2:=public.send_pool_invitation(pool,c);
 perform set_config('request.jwt.claim.sub',c::text,true);perform public.respond_pool_invitation(inv2,false);
 if public.get_my_pool_invitations()<>'[]'::jsonb then raise exception 'FAIL decline';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);inv2:=public.send_pool_invitation(pool,c);
 perform public.manage_pool_member(pool,null,'revoke');
 perform set_config('request.jwt.claim.sub',c::text,true);
 begin perform public.respond_pool_invitation(inv2,true);raise exception 'FAIL revoked';exception when raise_exception then if sqlerrm='FAIL revoked' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,true);inv2:=public.send_pool_invitation(pool,c);
 perform set_config('role','postgres',true);
 update public.invitations set created_at=now()-interval '9 days',expires_at=now()-interval '1 day' where id=inv2;
 perform set_config('request.jwt.claim.sub',c::text,true);perform set_config('role','authenticated',true);
 begin perform public.respond_pool_invitation(inv2,true);raise exception 'FAIL expired';exception when raise_exception then if sqlerrm='FAIL expired' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.delete_pool(pool);
 if exists(select 1 from public.pools where id=pool) then raise exception 'FAIL owner deletion';end if;
 if not exists(select 1 from public.tournament_entries where tournament_id=t and user_id=a) then raise exception 'FAIL central participation lost';end if;
 pool:=public.create_pool(t,'QA admin deletion');inv2:=public.send_pool_invitation(pool,c);
 perform set_config('request.jwt.claim.sub',admin_id::text,true);perform public.delete_pool(pool);
 perform set_config('request.jwt.claim.sub',a::text,true);pool:=public.create_pool(t,'QA super admin deletion');
 perform set_config('request.jwt.claim.sub',super_id::text,true);perform public.delete_pool(pool);
 perform set_config('role','postgres',true);
 if exists(select 1 from public.invitations where id in (inv,inv2)) then raise exception 'FAIL invitations not cascaded';end if;
 if exists(select 1 from public.pools where tournament_id=t) or exists(select 1 from public.pool_members m join public.pools p on p.id=m.pool_id where p.tournament_id=t) then raise exception 'FAIL deletion';end if;
 perform set_config('role','anon',true);
 begin perform public.get_my_pool_invitations();raise exception 'FAIL anonymous';exception when insufficient_privilege then null;end;
 perform set_config('role','postgres',true);
end $$;
rollback;
select 'PASS: search, selection IDs, invitations, acceptance, decline, expiry, revocation, owner/admin/super_admin deletion, authorization and cascade; all fixtures rolled back' as result;
